-- Uldum: loot table yang tidak ada di dump SFDB.
--
-- Latar belakang
--   Loot table creature zona ini kosong di DB ini, padahal
--   `creature_loot_template` secara keseluruhan sehat (368 ribu baris, 8768
--   tabel) dan zona MoP tidak punya satu pun lootid yang menggantung. Jadi ini
--   lubang khusus zona Cataclysm: mob-nya tidak menjatuhkan apa pun, uang
--   sekalipun, dan drop quest tidak pernah keluar.
--
-- Dibuat oleh tools/dev/port_zone_spawns.py --zone uldum --loot-out --
-- jangan diedit tangan, ubah skripnya lalu bangkitkan ulang.
--
-- Terjemahan skemanya, karena dua sisi tidak sama
--   4.3.4 memisahkan Reference dan QuestRequired jadi kolom sendiri; SkyFire
--   memampatkan keduanya ke dua kolom lama:
--     ChanceOrQuestChance = Chance, dinegatifkan kalau QuestRequired = 1
--                           (LootStoreItem menyimpannya sebagai needs_quest)
--     mincountOrRef       = -Reference kalau baris itu rujukan, selain itu MinCount
--   Baris IsCurrency dibuang: SkyFire tidak punya loot mata uang, dan id mata
--   uang yang masuk ke kolom item akan dibaca sebagai item yang tidak ada.
--
-- Idempotent dan tidak merusak: baris hanya masuk untuk loot table yang saat
-- ini benar-benar KOSONG. Kalau satu entry sudah punya loot, tabelnya dibiarkan
-- utuh -- tidak dicampur, tidak ditimpa.
--
-- Catatan: item yang tidak ada di `item_template` akan dilewati core sambil
-- menulis error di log `sql.sql`. Itu wajar untuk item Cataclysm yang tidak
-- terbawa ke 5.4.8, dan tidak menggagalkan impor.
--
-- Sumber: TDB_full_world_434.22011_2022_01_09.sql
-- Isi: 22165 baris creature_loot_template, 142 baris reference_loot_template.

DROP TABLE IF EXISTS `prabowow_uldum_ref_stage`;
CREATE TABLE `prabowow_uldum_ref_stage` (
    `entry` INT UNSIGNED NOT NULL,
    `item` INT UNSIGNED NOT NULL,
    `ChanceOrQuestChance` FLOAT NOT NULL,
    `lootmode` SMALLINT UNSIGNED NOT NULL,
    `groupid` TINYINT UNSIGNED NOT NULL,
    `mincountOrRef` INT NOT NULL,
    `maxcount` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`entry`, `item`)
);


-- Hanya loot table yang sekarang kosong yang diisi.
DROP TABLE IF EXISTS `prabowow_uldum_ref_pending`;
CREATE TABLE `prabowow_uldum_ref_pending` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY);
DELETE FROM `prabowow_uldum_ref_pending` WHERE `entry` IN (SELECT `entry` FROM `reference_loot_template`);

SELECT `s`.`entry`, `s`.`item`, `s`.`ChanceOrQuestChance`, `s`.`lootmode`, `s`.`groupid`, `s`.`mincountOrRef`, `s`.`maxcount` FROM `prabowow_uldum_ref_stage` `s`
JOIN `prabowow_uldum_ref_pending` `n` ON `n`.`entry` = `s`.`entry`;

DROP TABLE IF EXISTS `prabowow_uldum_ref_stage`;
DROP TABLE IF EXISTS `prabowow_uldum_ref_pending`;

DROP TABLE IF EXISTS `prabowow_uldum_loot_stage`;
CREATE TABLE `prabowow_uldum_loot_stage` (
    `entry` INT UNSIGNED NOT NULL,
    `item` INT UNSIGNED NOT NULL,
    `ChanceOrQuestChance` FLOAT NOT NULL,
    `lootmode` SMALLINT UNSIGNED NOT NULL,
    `groupid` TINYINT UNSIGNED NOT NULL,
    `mincountOrRef` INT NOT NULL,
    `maxcount` SMALLINT UNSIGNED NOT NULL,
    PRIMARY KEY (`entry`, `item`)
);














































-- Hanya loot table yang sekarang kosong yang diisi.
DROP TABLE IF EXISTS `prabowow_uldum_loot_pending`;
CREATE TABLE `prabowow_uldum_loot_pending` (`entry` INT UNSIGNED NOT NULL PRIMARY KEY);
DELETE FROM `prabowow_uldum_loot_pending` WHERE `entry` IN (SELECT `entry` FROM `creature_loot_template`);

SELECT `s`.`entry`, `s`.`item`, `s`.`ChanceOrQuestChance`, `s`.`lootmode`, `s`.`groupid`, `s`.`mincountOrRef`, `s`.`maxcount` FROM `prabowow_uldum_loot_stage` `s`
JOIN `prabowow_uldum_loot_pending` `n` ON `n`.`entry` = `s`.`entry`;

DROP TABLE IF EXISTS `prabowow_uldum_loot_stage`;
DROP TABLE IF EXISTS `prabowow_uldum_loot_pending`;

